package build

import (
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

// pruneNodeWeightDest is where fetch-base writes the npm weight prune. Like
// freeze-git and the glab shim it is generated by a printf block, so it is
// reassembled from the Dockerfile rather than read off disk — and it is *run*,
// because the thing it has to get right is which files survive it.
const pruneNodeWeightDest = "/usr/local/bin/prune-node-weight"

// TestFinalStageInstallsNothingFromAPackageRegistry holds the invariant the tail
// emptying established: no npm or pip install may live in the final stage.
//
// Every such RUN is parent-chained below the deliberately-unpinned apt layer, so
// an Archive Drift rebuilds it whole and re-pushes it to every puller for nothing
// anyone edited — measured at 587 MB of 639 on a one-line bump before the moves.
// A `COPY --link` from a `fetch-*` stage moves only when its own `/out` bytes
// change, which is where an npm or pip tree belongs.
//
// apt is deliberately NOT matched: `COPY --link` carries files, not dpkg state,
// so a package genuinely has to be installed here, and the base apt layer is the
// cheapest place for it — a drift rebuilds that layer anyway. corepack is not
// matched either: it materialises pnpm into a cache keyed on the node runtime
// rather than into a prefix a COPY could carry, which is why pnpm is the one
// install left in the stage.
//
// → ADR 0002 follow-up 2, .claude/rules/image-build.md
func TestFinalStageInstallsNothingFromAPackageRegistry(t *testing.T) {
	// Comments have to go first: the stage describes what it no longer does
	// (the NPM_CONFIG knobs exist for a runtime `npm install` by the user), and
	// a needle that matches prose fails on the documentation rather than the
	// build — the same trap dockerfileStages avoids for `git clone`.
	var body strings.Builder
	for line := range strings.SplitSeq(finalStage(t), "\n") {
		if strings.HasPrefix(strings.TrimSpace(line), "#") {
			continue
		}
		body.WriteString(line)
		body.WriteString("\n")
	}

	// Deliberately narrow literals rather than a clever regex: the repo's own
	// rule about this parse (TestSmokeTestVendorCompletionsFloor) is that the
	// pattern is the fragile half. A spelling these two miss is not the
	// regression this guards — a whole install layer reappearing is.
	for _, install := range []string{"npm install", "pip install"} {
		if strings.Contains(body.String(), install) {
			t.Errorf("the final stage runs %q — an install there is rebuilt by every Debian archive update and re-pushed to every puller; put it in a fetch-<tool> stage and COPY --link its /out", install)
		}
	}
}

// TestNodeStagesShareOneBaseImage holds the coupling that makes the npm and pip
// fetch stages valid: each of them builds a tree the FINAL stage's runtime has to
// read back, so the node image is named once, as `node-base`, and every stage
// that needs it derives from that.
//
// For npm that is the rule fetch-codegraph established — a global node_modules
// tree is only valid on the runtime that resolved it. For pip it is the same
// hazard one layer down: `fetch-graphify` installs with `pip --root /out`, whose
// destination is `dist-packages` under the interpreter's own minor version, so a
// stage on another Debian release lands the tree on a path the final image's
// python3 never scans. Both failures are silent at build time, which is why the
// agreement is structural rather than asserted per stage: one reference for
// Renovate to bump, and a second spelling of it is what this test refuses.
func TestNodeStagesShareOneBaseImage(t *testing.T) {
	const alias = "node-base"

	var direct []string
	var sawAlias bool
	for line := range strings.SplitSeq(readAsset(t, "Dockerfile"), "\n") {
		if !strings.HasPrefix(line, "FROM ") {
			continue
		}
		ref, rest, _ := strings.Cut(strings.TrimPrefix(line, "FROM "), " ")
		named := strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(rest), "AS "))
		if !strings.HasPrefix(ref, "node:") {
			continue
		}
		if named == alias {
			sawAlias = true
			continue
		}
		direct = append(direct, line)
	}

	if !sawAlias {
		t.Fatalf("no `FROM node:<ref> AS %s` stage in the Dockerfile — the node image has to be named once, and every stage that resolves an npm global tree or a pip dist-packages path has to derive from it", alias)
	}
	for _, line := range direct {
		t.Errorf("%q names the node image directly — derive from `%s` instead, so there is one reference to bump and no way for two stages to drift onto different runtimes", line, alias)
	}
}

// TestPruneNodeWeightSparesSkillTrees runs the reassembled weight prune over a
// tree shaped like the packages it is pointed at.
//
// The prune deletes any `*.md`, which is fine until a tool ships markdown it
// *uses*: playwright-cli's skills are `SKILL.md` plus a `references/` tree, and
// emptying them produces an empty skill behind a green build. That is not
// hypothetical — it shipped once, when an upstream relocation turned a
// path-based exclusion into a no-op. The exclusion is therefore by directory
// *name*, and it lives in the shared helper rather than in one stage's copy of
// the find, so a new npm stage cannot forget it.
func TestPruneNodeWeightSparesSkillTrees(t *testing.T) {
	dir := t.TempDir()
	script := filepath.Join(dir, "prune-node-weight")
	if err := os.WriteFile(script, []byte(extractPrintfScript(t, pruneNodeWeightDest)), 0o755); err != nil {
		t.Fatalf("write helper: %v", err)
	}

	tree := filepath.Join(dir, "node_modules", "pkg")
	// Left of the slash: what the prune must remove. Right: what it must keep.
	// The skills entries are markdown that would match the weight rules exactly
	// were it not for the name-based directory exclusion above them.
	gone := []string{
		"README.md", "CHANGELOG.md", "AUTHORS.txt",
		"lib/bundle.js.map",
		"docs/guide.md", "examples/demo.js", "example/demo.js",
		"__tests__/spec.js", ".github/workflows/ci.yml",
	}
	kept := []string{
		"lib/bundle.js", "package.json",
		"lib/tools/skills/playwright-cli/SKILL.md",
		"lib/tools/skills/playwright-cli/references/api.md",
		"lib/tools/skill/legacy/SKILL.md",
	}
	for _, rel := range append(append([]string{}, gone...), kept...) {
		path := filepath.Join(tree, rel)
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatalf("mkdir %s: %v", path, err)
		}
		if err := os.WriteFile(path, []byte("x"), 0o644); err != nil {
			t.Fatalf("write %s: %v", path, err)
		}
	}

	if out, err := exec.Command("sh", script, tree).CombinedOutput(); err != nil {
		t.Fatalf("prune-node-weight %s: %v\n%s", tree, err, out)
	}

	for _, rel := range kept {
		if _, err := os.Stat(filepath.Join(tree, rel)); err != nil {
			t.Errorf("%s was pruned and must not be: %v", rel, err)
		}
	}
	var survived []string
	for _, rel := range gone {
		if _, err := os.Stat(filepath.Join(tree, rel)); err == nil {
			survived = append(survived, rel)
		}
	}
	sort.Strings(survived)
	if len(survived) > 0 {
		t.Errorf("the prune left %v behind — the weight rules stopped matching", survived)
	}

	// No argument is the shape a refactor produces by accident (an empty shell
	// variable expanding to nothing), and `find` with no path walks the current
	// directory. Refusing it is what keeps that from pruning the build root.
	if err := exec.Command("sh", script).Run(); err == nil {
		t.Error("prune-node-weight with no argument succeeded — it has to refuse, or an empty expansion prunes the working directory")
	}
}
